function captureSetInput(el){const row=el.closest('.set-row');if(!row||el.type!=='number')return false;const entry=state.draft?.exercises.find(x=>x.id===row.dataset.id),set=entry?.sets[+row.dataset.set];if(!set)return false;const result=C.parseSetField(el.dataset.field,el.value),values=el.dataset.side?set.sideRecords?.[el.dataset.side]:set;if(!values)return false;el.setAttribute('aria-invalid',String(!result.valid));if(!result.valid){if(set.done){set.done=false;save();}return true;}values[el.dataset.field]=result.value;if(set.done&&!C.validSet(set))set.done=false;save();return true;}
